import json, csv, re
old = {q['id']: q for q in json.load(open('/workspace/p3-math-3a-quiz/questions.json'))}
TOP = {1:'五位數',2:'乘法',3:'毫米和公里',4:'秒和24小時報時制'}
out=[]; rep=[]
def add(id_, L, q, src, ex, opts=None, ans=None, val=None, status=None, note=''):
    d={'id':str(id_),'lesson':L,'topic':TOP[L]}
    if val is not None:
        d.update(type='input', q=q, source=src, explain=ex, answerValue=str(val))
    else:
        assert ans in opts and len(opts)==4 and len(set(opts))==4, (id_,opts,ans)
        d.update(type='mcq', q=q, source=src, explain=ex, options=opts, answer=opts.index(ans))
    out.append(d)
    o=old.get(str(id_))
    if status is None: status = 'added' if o is None else ('ok' if o['source']==src else 'fixed')
    rep.append([id_, status, o['source'] if o else '', src, note])
